using System.ComponentModel.DataAnnotations;

namespace FarmAI.Models;
public class LoginForm { [Required] public string Username { get; set; } = ""; [Required] public string Password { get; set; } = ""; }
public class BarnForm { [Required, MaxLength(32)] public string Code { get; set; } = ""; [Required] public string Name { get; set; } = ""; [Required] public string Species { get; set; } = ""; [Range(1,1000000)] public int Capacity { get; set; } }
public class HerdForm { [Required] public string Code { get; set; } = ""; [Required] public string Name { get; set; } = ""; [Required] public string Species { get; set; } = ""; public string? Breed { get; set; } public string? Purpose { get; set; } public Guid BarnId { get; set; } [Range(1,10000000)] public int Quantity { get; set; } }
public class TransferForm { public Guid HerdId { get; set; } public Guid TargetBarnId { get; set; } public int Version { get; set; } }
public class SplitForm { public Guid SourceHerdId { get; set; } public Guid TargetHerdId { get; set; } [Range(1,10000000)] public int Quantity { get; set; } }
public class MovementForm { public Guid HerdId { get; set; } [Range(-10000000,10000000)] public int Delta { get; set; } = -1; [Required] public string Kind { get; set; } = "DEATH"; [Required] public string Reason { get; set; } = ""; public Guid RequestKey { get; set; } = Guid.NewGuid(); }
public class CareForm { public Guid HerdId { get; set; } public string Kind { get; set; } = "FEED"; [Required] public string ItemName { get; set; } = ""; public string Unit { get; set; } = "kg"; [Range(typeof(decimal),"0.001","1000000000")] public decimal Quantity { get; set; } [Range(typeof(decimal),"0","100000000000")] public decimal? UnitPrice { get; set; } public string? Reference { get; set; } public string? Note { get; set; } }
public class GrowthForm { public Guid HerdId { get; set; } [Range(1,1000000)] public int SampleSize { get; set; } [Range(typeof(decimal),"0.001","10000000")] public decimal WeightKg { get; set; } public string Method { get; set; } = "RANDOM"; public DateTime MeasuredAt { get; set; } = DateTime.UtcNow; }
public class AnimalForm { public Guid HerdId { get; set; } [Required] public string Tag { get; set; } = ""; public string Sex { get; set; } = "FEMALE"; }
public class ReproductionForm { public Guid MotherId { get; set; } public Guid TargetHerdId { get; set; } [Range(0,100000)] public int LiveBorn { get; set; } [Range(0,100000)] public int StillBorn { get; set; } [Range(0,100000)] public int Accepted { get; set; } public Guid RequestKey { get; set; } = Guid.NewGuid(); }
public class PlanForm { public Guid HerdId { get; set; } public Guid VaccineId { get; set; } public DateOnly PlannedDate { get; set; } = DateOnly.FromDateTime(DateTime.Today.AddDays(3)); [Range(1,1000000)] public int Target { get; set; } public Guid AssignedTo { get; set; } [Required] public string Reference { get; set; } = ""; }
public class VaccinationEventForm { public Guid PlanId { get; set; } [Range(1,100000)] public int Quantity { get; set; } [Required] public string Lot { get; set; } = ""; public Guid RequestKey { get; set; } = Guid.NewGuid(); }
public class SaleForm { [Required] public string CustomerName { get; set; } = ""; public Guid HerdId { get; set; } [Range(1,1000000)] public int Quantity { get; set; } public decimal? WeightKg { get; set; } public string Basis { get; set; } = "HEAD"; public decimal UnitPrice { get; set; } }
public class LineForm { public Guid SaleId { get; set; } public Guid HerdId { get; set; } public int Quantity { get; set; } public decimal? WeightKg { get; set; } public string Basis { get; set; } = "HEAD"; public decimal UnitPrice { get; set; } }
public class PaymentForm { public Guid SaleId { get; set; } [Range(typeof(decimal),"1","999999999999")] public decimal Amount { get; set; } public string Method { get; set; } = "CASH"; public string? Reference { get; set; } }
public class UserForm { [Required] public string Username { get; set; } = ""; [Required, MinLength(8)] public string Password { get; set; } = ""; public string Role { get; set; } = Roles.Employee; }
